#include "wifi.h"
#include "config.h"
#include <windows.h>
#include <wlanapi.h>
#include <algorithm>
#pragma comment(lib,"wlanapi.lib")
static std::wstring SsidText(const DOT11_SSID& s){return std::wstring(s.ucSSID,s.ucSSID+s.uSSIDLength);}
static bool Prefix(const std::wstring& s){return s.rfind(L"QVTU",0)==0;}
struct WlanSession { HANDLE h{}; PWLAN_INTERFACE_INFO_LIST interfaces{}; ~WlanSession(){if(interfaces)WlanFreeMemory(interfaces);if(h)WlanCloseHandle(h,nullptr);} bool Open(){DWORD v=0;return WlanOpenHandle(2,nullptr,&v,&h)==ERROR_SUCCESS&&WlanEnumInterfaces(h,nullptr,&interfaces)==ERROR_SUCCESS&&interfaces;}};
std::vector<WifiChoice> ListQvtuWifi(bool savedOnly){std::vector<WifiChoice> out;WlanSession s;if(!s.Open())return out;for(DWORD i=0;i<s.interfaces->dwNumberOfItems;i++){auto& inf=s.interfaces->InterfaceInfo[i];PWLAN_PROFILE_INFO_LIST pl=nullptr;WlanGetProfileList(s.h,&inf.InterfaceGuid,nullptr,&pl);std::vector<std::wstring> saved;if(pl){for(DWORD k=0;k<pl->dwNumberOfItems;k++){std::wstring name=pl->ProfileInfo[k].strProfileName;if(Prefix(name))saved.push_back(name);}WlanFreeMemory(pl);}for(const auto& name:saved)out.push_back({name,0});if(!savedOnly){PWLAN_AVAILABLE_NETWORK_LIST nl=nullptr;WlanGetAvailableNetworkList(s.h,&inf.InterfaceGuid,0,nullptr,&nl);for(DWORD j=0;nl&&j<nl->dwNumberOfItems;j++){auto& n=nl->Network[j];std::wstring name=SsidText(n.dot11Ssid);if(Prefix(name))out.push_back({name,(int)n.wlanSignalQuality});}if(nl)WlanFreeMemory(nl);}}std::sort(out.begin(),out.end(),[](auto&a,auto&b){return a.signal>b.signal;});out.erase(std::unique(out.begin(),out.end(),[](auto&a,auto&b){return a.ssid==b.ssid;}),out.end());return out;}
bool IsWifiConnected(std::wstring& current){current.clear();WlanSession s;if(!s.Open())return false;for(DWORD i=0;i<s.interfaces->dwNumberOfItems;i++){PWLAN_CONNECTION_ATTRIBUTES a=nullptr;DWORD size=0;WLAN_OPCODE_VALUE_TYPE type;if(WlanQueryInterface(s.h,&s.interfaces->InterfaceInfo[i].InterfaceGuid,wlan_intf_opcode_current_connection,nullptr,&size,(PVOID*)&a,&type)==ERROR_SUCCESS&&a){if(a->isState==wlan_interface_state_connected){current=SsidText(a->wlanAssociationAttributes.dot11Ssid);WlanFreeMemory(a);return true;}WlanFreeMemory(a);}}return false;}
bool EnableWifiRadio(std::wstring& error){WlanSession s;if(!s.Open()){error=L"无法访问 Windows WLAN 服务。";return false;}bool any=false;for(DWORD i=0;i<s.interfaces->dwNumberOfItems;i++){WLAN_PHY_RADIO_STATE state{};state.dwPhyIndex=0;state.dot11SoftwareRadioState=dot11_radio_state_on;state.dot11HardwareRadioState=dot11_radio_state_on;DWORD r=WlanSetInterface(s.h,&s.interfaces->InterfaceInfo[i].InterfaceGuid,wlan_intf_opcode_radio_state,sizeof(state),&state,nullptr);if(r==ERROR_SUCCESS)any=true;}if(!any)error=L"Windows 未允许打开 Wi-Fi 无线电，可能受飞行模式、硬件开关或系统策略限制。";return any;}
bool PrepareQvtuWifi(const std::wstring& fixedSsid,bool& connected,std::wstring& error){connected=false;auto profiles=ListQvtuWifi(true);if(profiles.empty()){error=L"未找到已保存的 QVTU_ Wi-Fi，请先在 Windows Wi-Fi 设置中保存网络。";return false;}WifiChoice pick=profiles.front();if(!fixedSsid.empty()){auto it=std::find_if(profiles.begin(),profiles.end(),[&](auto&x){return x.ssid==fixedSsid;});if(it==profiles.end()){error=L"指定的 QVTU_ Wi-Fi 未保存："+fixedSsid;return false;}pick=*it;}WlanSession s;if(!s.Open()){error=L"无法访问 Windows WLAN 服务。";return false;}for(DWORD i=0;i<s.interfaces->dwNumberOfItems;i++){WLAN_CONNECTION_PARAMETERS cp{};cp.wlanConnectionMode=wlan_connection_mode_profile;cp.strProfile=pick.ssid.c_str();cp.dot11BssType=dot11_BSS_type_infrastructure;if(WlanConnect(s.h,&s.interfaces->InterfaceInfo[i].InterfaceGuid,&cp,nullptr)!=ERROR_SUCCESS)continue;for(int t=0;t<24;t++){Sleep(500);std::wstring current;if(IsWifiConnected(current)&&current==pick.ssid){connected=true;Log(L"已连接 Wi-Fi："+pick.ssid);return true;}}}error=L"连接 QVTU_ Wi-Fi 超时："+pick.ssid;return false;}
